/// <summary>
/// Extension of GUPItemBasePriceCalcJob
/// </summary>
[ExtensionOf(classStr(GUPItemBasePriceCalcJob_All))]
internal final class METGUPItemBasePriceCalcJob_All_extension
{
}

Method.Source:
/// <summary>
/// run method
/// </summary>
public void run()
{
    // MS SR# - 2512100060001510 -- begin
    // this is a temporary fix provided by MS
    // this coding has to be removed once MS provices the quality update
    calcDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    sessionGuid = newGuid();

    if (this.parmBasePriceDeltaCalculation())
    {
        Set itemIdSet = new Set(Types::String);
        GUPVendPriceAdmTrans vendPriceAdmTrans;
        GUPVendPriceAdmTable vendPriceAdmTable;
        while select ItemNum from vendPriceAdmTrans
                where vendPriceAdmTrans.IsDirty == GUPNoYesMarked::Yes
            join RecId from vendPriceAdmTable
                where vendPriceAdmTable.JournalNum == vendPriceAdmTrans.JournalNum
                   && vendPriceAdmTable.Status == GUPDisabledEnabled::Enabled
                   && vendPriceAdmTable.InventSiteId == this.parmSiteId()
        {
            itemIdSet.add(vendPriceAdmTrans.ItemNum);
        }

        GUPPriceTermJournalTrans priceTermJournalTrans;
        GUPPriceTermJournalTable priceTermJournalTable;
        Query lineQuery;
        QueryRun qr;
        QueryBuildDataSource inventTableDS;
        GUPPricingRuleCondition ruleCondition;

        while select PricingRule from priceTermJournalTrans
                where priceTermJournalTrans.IsDirty == GUPNoYesMarked::Yes
            join RecId from priceTermJournalTable
                where priceTermJournalTable.AgreementId == priceTermJournalTrans.AgreementId
                   && priceTermJournalTable.Status == GUPDisabledEnabled::Enabled
                   && priceTermJournalTable.InventSiteId == this.parmSiteId()
            join ConditionValue from ruleCondition
            where ruleCondition.ruleId == priceTermJournalTrans.PricingRule
        {
            itemIdSet.add(ruleCondition.ConditionValue);
        }
        str queryCondition;
        SetEnumerator setEnumerator = itemIdSet.getEnumerator();
        while (setEnumerator.moveNext())
        {
            queryCondition += queryCondition ? ',' + setEnumerator.current() : setEnumerator.current();
        }

        Query query = queryRun.query();
        QueryBuildDataSource qbds = query.dataSourceTable(tablenum(InventTable));
        qbds.addRange(fieldNum(InventTable, ItemId)).value(queryCondition);
        queryRun = new QueryRun(query);

    }
    // MS SR# - 2512100060001510 -- end

    next run();
    if (this.parmMETIncludeClaimFromVendor())
    {
        METVendClaimProcessJob::contructMETVendClaimProcessTasks(this.parmCalcDate(), this.parmSiteId(), this);
    }
}
